 # pulse.enable = true;
 # };

 # --- 5. ТАЧПАД ---
 # services.libinput.enable = true;

 # --- 6. ПОЛЬЗОВАТЕЛЬ ---
 # users.users.alice = {
 # isNormalUser = true;
 # extraGroups = [ "wheel" ];
 # packages = with pkgs; [
